VALUES ('leonard.hayes@harmonygames.co/<LV3PR19MB85246D2E9B14C7A03F5E8D12BC4A7@LV3PR19MB8524.namprd19.prod.outlook.com>', 'leonard.hayes@harmonygames.co/1857029474983245439', 'leonard.hayes@harmonygames.co', '["INBOX", "IMPORTANT", "Label_b19fb8d1b3", "CATEGORY_PERSONAL"]', 'Thank you Leonard. Two clarifications on our side. For item 2, a line terminated on or before the as-of date counts only what had vested by ', 1771004235000, '2026-02-13T17:37:15Z', 1326, 'RE: GRIFFIN GAMING PARTNERS 2025 Audit Request [SOURCE_ORG_0001], Inc.', 'PERSON_3088_EMAIL', 'PERSON_3088_NAME', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '["PERSON_4416_NAME <PERSON_4416_EMAIL>", "PERSON_2322_NAME <PERSON_2322_EMAIL>", "PERSON_2847_EMAIL"]', '[]', '[]', E'Thank you Leonard. Two clarifications on our side. For item 2, a line terminated on or before the as-of date counts only what had vested by its termination date. For item 4, we need any new financing and whether the company is winding down.\r\n\r\nThank you,\r\n\r\n[PERSON_NAME_46103] (she/her/[PERSON_NAME_13208])\r\nAudit Associate\r\nKPMG LLP | 55 Second Street | Suite 1400 | San Francisco, CA 94105\r\nPERSON_3088_EMAIL\r\nkpmg.com/us\r\n', NULL, '[{"name": "Message-ID", "value": "<LV3PR19MB85246D2E9B14C7A03F5E8D12BC4A7@LV3PR19MB8524.namprd19.prod.outlook.com>"}, {"name": "Date", "value": "Fri, 13 Feb 2026 17:37:15 +0000"}, {"name": "Subject", "value": "RE: GRIFFIN GAMING PARTNERS 2025 Audit Request [SOURCE_ORG_0001], Inc."}, {"name": "From", "value": "PERSON_3088_NAME <PERSON_3088_EMAIL>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}, {"name": "Cc", "value": "PERSON_4416_NAME <PERSON_4416_EMAIL>, PERSON_2322_NAME <PERSON_2322_EMAIL>, PERSON_2847_EMAIL"}, {"name": "In-Reply-To", "value": "<CAPBs_a7Tq2LmV9xYcR4KdN8wUe3HsJ6oFbZ1gPiA5tGyQnE0Xw@mail.gmail.com>"}, {"name": "References", "value": "<LV3PR19MB8524F1C07D3A94E26B58D0AC7A1E2@LV3PR19MB8524.namprd19.prod.outlook.com> <CAPBs_a7Tq2LmV9xYcR4KdN8wUe