VALUES ('leonard.hayes@harmonygames.co/<mlkq74xd.3f9e2c1a-6b48-4d07-a1e5-8c2f0d7b6a94@we.are.superhuman.com>', 'leonard.hayes@harmonygames.co/1857034369525983506', 'leonard.hayes@harmonygames.co', '["INBOX", "IMPORTANT", "Label_b19fb8d1b3", "CATEGORY_PERSONAL"]', 'Hi Leonard, Quick one from legal for the intake. Before they start on the stockholder side they''ll need this from you, ideally in one sheet:', 1771005981000, '2026-02-13T18:06:21Z', 1648, 'Sunset: stockholder info for intake', 'PERSON_2888_EMAIL', 'PERSON_2888_NAME', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '[]', '[]', '[]', E'Hi Leonard,\r\n\r\nQuick one from legal for the intake. Before they start on the stockholder side they''ll need this from you, ideally in one sheet:\r\n\r\n- One line per holder of stock or options, with what each holds today (for options, what''s vested) and any last day\r\n- Total shares and options outstanding\r\n- A count of holders by what each still needs to hear from you\r\n- Directors in office, and who holds the preferred vote\r\n\r\nFormal notices are a separate step that legal will walk you through later, so your own notes to holders don''t need to double as notices.\r\n\r\nBest,\r\nPERSON_2888_NAME\r\nHead of Partnerships\r\nM: [PHONE_15402]\r\nW: www.sunsethq.com ( http://www.sunsethq.com/ )\r\n\r\nSent via Superhuman ( https://sprh.mn/?vip=PERSON_2888_EMAIL )\r\n', NULL, '[{"name": "Message-ID", "value": "<mlkq74xd.3f9e2c1a-6b48-4d07-a1e5-8c2f0d7b6a94@we.are.superhuman.com>"}, {"name": "Date", "value": "Fri, 13 Feb 2026 18:06:21 +0000"}, {"name": "Subject", "value": "Sunset: stockholder info for intake"}, {"name": "From", "value": "PERSON_2888_NAME <PERSON_2888_EMAIL>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
