VALUES ('leonard.hayes@harmonygames.co/<CAJr7mPx2QwF8nVb4LtK9sYd3HcE6uZaR1oGiN5tMeBq0WsXkQz@mail.gmail.com>', 'leonard.hayes@harmonygames.co/1856121753612004097', 'leonard.hayes@harmonygames.co', '["INBOX", "IMPORTANT", "Label_b19fb8d1b3", "CATEGORY_PERSONAL"]', 'Fyi, this came through from Carta. Thanks for sorting out the extra weeks I asked for. Calvin ---------- Forwarded message --------- From: S', 1770135644000, '2026-02-03T16:20:44Z', 2770, 'Fwd: Your option grant at [SOURCE_ORG_0001] Games Inc. has been updated', '[EMAIL_0801]', 'Calvin Price', '["leonard hayes <leonard.hayes@harmonygames.co>"]', '[]', '[]', '[]', E'Fyi, this came through from Carta. Thanks for sorting out the extra weeks I asked for.\r\n\r\nCalvin\r\n\r\n---------- Forwarded message ---------\r\nFrom: SVC_0077_NAME <SVC_0077_EMAIL>\r\nDate: Fri, Jan 23, 2026 at 10:05 AM\r\nSubject: Your option grant at [SOURCE_ORG_0001] Games Inc. has been updated\r\nTo: <[EMAIL_0801]>\r\n\r\n= Your option grant has been updated. =\r\n\r\n  [SOURCE_ORG_0001] Games Inc. has extended the post-termination exercise period on your\r\noption grant. Current holdings and overview of the changes summarized below: \r\n\r\n Equity awards     ID ES-3   Acceptance status Accepted   Granted 8,138  \r\nVested 4,408   Exercised 0   Grant date Nov. 10, 2023   Termination date\r\nOct. 24, 2025   Last day to exercise Feb. 20, 2026 (previously Jan. 24, 2026)    \r\n \r\n  \r\n       Learn more about Carta <https://Carta.com>   •   Visit Carta’s\r\nKnowledge Base <https://support.Carta.com>   •   Release Notes\r\n<https://releasenotes.Carta.com/>   •   Equity Education Center\r\n<https://Carta.com/equity/learn/what-is-equity/?utm_campaign=q2_2022_corps_us_core-Carta-equity-101-launch&amp;utm_medium=email&amp;utm_source=product&amp;utm_content=>\r\n\r\n\r\n  The contents of this e-mail message and any attachments are confidential\r\nand may be legally privileged. If you are not the intended recipient,\r\nnotify the sender and delete this message and its attachments, if any. \r\n\r\n  To ensure delivery to your inbox, add SVC_0077_EMAIL\r\n<mailto:SVC_0077_EMAIL>, SVC_5909_EMAIL <mailto:SVC_5909_EMAIL>,\r\nand SVC_4490_EMAIL <mailto:SVC_4490_EMAIL> to your address book. \r\n\r\n  For Carta Support, log in and open the Carta Help Center from the user\r\nmenu at the top right of the page. Open Carta Help Center →\r\n<https://app.Carta.com/profiles/update/?help=true> \r\n\r\n  eShares, Inc. DBA Carta, Inc. \r\n 333 Bush Street, Suite 2300 \r\n San Francisco, CA 94104 \r\n [PHONE_14952] <tel:[PHONE_14951]>', NULL, '[{"name": "Message-ID", "value": "<CAJr7mPx2QwF8nVb4LtK9sYd3HcE6uZaR1oGiN5tMeBq0WsXkQz@mail.gmail.com>"}, {"name": "Date", "value": "Tue, 03 Feb 2026 10:20:44 -0600"}, {"name": "Subject", "value": "Fwd: Your option grant at [SOURCE_ORG_0001] Games Inc. has been updated"}, {"name": "From", "value": "Calvin Price <[EMAIL_0801]>"}, {"name": "To", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}]', NULL, NULL, NULL, '[]');
