VALUES ('leonard.hayes@harmonygames.co/<CAPBs_aLeDrdRoqOb0LrQ1AfGvbpmR-YdoG8A6PGmPay5Sc-ng=@mail.gmail.com>', 'leonard.hayes@harmonygames.co/1856961760270377901', 'leonard.hayes@harmonygames.co', '["SENT", "Label_b19fb8d1b3"]', 'Hi Akin, Not the note I hoped to write. Harmony is shutting down: we let the team know yesterday, and Robert and I are handling the wind-dow', 1770936737000, '2026-02-12T22:52:17Z', 1177, 'Harmony', 'leonard.hayes@harmonygames.co', 'leonard hayes', '["Husnu Akin <PERSON_8862_EMAIL>"]', '[]', '[]', '[]', E'Hi Akin,\r\n\r\nNot the note I hoped to write. Harmony is shutting down: we let the team know yesterday, and Robert and I are handling the wind-down from here.\r\n\r\nI''ll come back to you once the paperwork side is clear. Thank you for everything, on the board and since.\r\n\r\nLeonard\r\n', NULL, '[{"name": "Message-ID", "value": "<CAPBs_aLeDrdRoqOb0LrQ1AfGvbpmR-YdoG8A6PGmPay5Sc-ng=@mail.gmail.com>"}, {"name": "Date", "value": "Thu, 12 Feb 2026 14:52:17 -0800"}, {"name": "Subject", "value": "Harmony"}, {"name": "From", "value": "leonard hayes <leonard.hayes@harmonygames.co>"}, {"name": "To", "value": "Husnu Akin <PERSON_8862_EMAIL>"}]', NULL, NULL, NULL, '[]');
UPDATE gmail.gmail_messages SET body_text = E'Hi [PERSON_NAME_0613],\n\n\nThank you for reaching out and apologies for not responding previously, we\nmissed the email. Please find below the requested information regarding\n[SOURCE_ORG_0001] Games Inc. to facilitate the setup of our workers’ compensation\naccount.\n\n   1.\n\n   Business Operations:\n   [SOURCE_ORG_0001] Games Inc. is a mobile game development company focused on\n   creating engaging and interactive digital entertainment experiences. Our\n   primary operations involve the design, development, testing, and\n   maintenance of mobile gaming applications for a global audience.\n\n   2.\n\n   Employee Job Duties and Activities in Washington:\n\n   -\n\n      Currently we have one Washington-based employee in a senior\n      marketing  and business development role.\n      -\n\n      Duties:\n      -\n\n         Vice President of Marketing and Business Development\n         (Washington-based): Manages marketing strategy, business\n         partnerships, and growth initiatives, including identifying new market\n         opportunities and overseeing promotional campaigns.\n         -\n\n      Location of work: Most work is performed remotely from Washington State, with a few times a year in-person meetings or collaborations. This\n      pe[USERNAME_10461] does infrequently need to travel for the work.\n      3.\n\n   Employee Start Date:\n   Our Washington-based employee began work on September 4, 2024.\n\n   4.\n\n   Business Acquisition:\n   [SOURCE_ORG_0001] Games Inc. was not acquired from another business.\n\n   5.\n\n   Mailing Address:\n   [SOURCE_ORG_0001] Games Inc.\n   3116 Weddington Rd Ste 900 PMB 2017\n   [PERSON_NAME_0949], North Carolina 28105-9407\n   United States\n\n   6.\n\n   Physical Location in Washington:\n   [SOURCE_ORG_0001] Games Inc. does not currently operate from a physical location\n   in Washington.\n\n   7.\n\n   Primary Contact for the Business:\n\n   -\n\n      Name: Leonard Hayes\n      -\n\n      Email: leonard.hayes@harmonygames.co\n      -\n\n      Phone Number: [PHONE_3804]\n      8.\n\n   Ownership Information: I don''t have the SSN for international owners and\n   institutional owners but here is the entire list. Let me know how you want\n   me to proceed with this information.\n\n   -\n\n      Owners:\n      -\n\n         GRIFFIN GAMING PARTNERS – 2,746,693 shares – 27.278% diluted\n         ownership\n         -\n\n         Arthur Blake – 2,000,000 shares – 19.863% diluted ownership\n         -\n\n         [PERSON_NAME_0055] – 2,000,000 shares – 19.863% diluted ownership\n         -\n\n         Leonard Hayes – 2,000,000 shares – 19.863% diluted ownership\n         -\n\n         [PERSON_NAME_0038] – 127,162 shares – 1.263% diluted ownership\n         -\n\n         [PERSON_NAME_11362] – 86,470 shares – 0.859% diluted ownership\n         -\n\n         [PERSON_NAME_0089] [PERSON_NAME_25152] – 81,383 shares – 0.808% diluted ownership\n         -\n\n         TOR Capital Limited – 50,865 shares – 0.505% diluted ownership\n         -\n\n         [PERSON_NAME_2768] [PERSON_NAME_0011] – 35,605 shares – 0.354% diluted ownership\n         -\n\n         PERSON_3941_NAME [PERSON_NAME_0127] – 31,536 shares – 0.313% diluted ownership\n         -\n\n         PERSON_1287_NAME – 31,536 shares – 0.313% diluted ownership\n         -\n\n         [PERSON_NAME_0043] – 30,519 shares – 0.303% diluted ownership\n         -\n\n         Victor [PERSON_NAME_2770] [PERSON_NAME_0086] – 30,519 shares – 0.303% diluted ownership\n         -\n\n         [PERSON_NAME_52949] – 25,432 shares – 0.253% diluted ownership\n         -\n\n         Arthur PERSON_3083_NAME – 25,432 shares – 0.253% diluted ownership\n         -\n\n         Patrick Lewis – 25,432 shares – 0.253% diluted ownership\n         -\n\n         [PERSON_NAME_4468] – 25,432 shares – 0.253% diluted ownership\n         -\n\n         [PERSON_NAME_27652] – 25,432 shares – 0.253% diluted ownership\n         -\n\n         Marcus Bennett – 22,889 shares – 0.227% diluted ownership\n         -\n\n         [PERSON_NAME_0068] – 16,277 shares – 0.162% diluted ownership\n         -\n\n         [PERSON_NAME_0022] [PERSON_NAME_32704] – 15,259 shares – 0.152% diluted ownership\n         -\n\n         [PERSON_NAME_0612] – 10,173 shares – 0.101% diluted ownership\n         -\n\n         [PERSON_NAME_2769] [PERSON_NAME_0093] – 10,173 shares – 0.101% diluted ownership\n         -\n\n         Calvin Price – 8,138 shares – 0.081% diluted ownership\n         -\n\n         Claire Morgan – 7,630 shares – 0.076% diluted ownership\n         -\n\n         Martin Georgiev Walsh – 3,866 shares – 0.038% diluted ownership\n         -\n\n         [PERSON_NAME_0051] – 3,866 shares – 0.038% diluted ownership\n\nWe will also complete the Change in Governing People form as requested and\nreturn it via fax or mail.\n\nPlease let us know if you require any additional information, and thank you\nfor guiding us through this process.\n\nBest regards,\nLeonard Hayes\nCEO, [SOURCE_ORG_0001] Games Inc.\nleonard.hayes@harmonygames.co\n[PHONE_3804]\n\n\n\nOn Tue, Nov 26, 2024 at 10:45 AM Arthur Blake <arthur.blake@harmonygames.co>\nwrote:\n\n> Hi [PERSON_NAME_0613],\n>\n> Our CEO, Leonard, should be able to help with this information. I''ve CC''ed\n> him.\n>\n> Thanks,\n>\n> PERSON_3083_NAME\n>\n>\n>\n> On Tue, Nov 26, 2024 at 12:25 PM Acopan, [PERSON_NAME_11623] (LNI) <\n> PERSON_0242_EMAIL> wrote:\n>\n>> ***FINAL REQUEST***\n>>\n>>\n>>\n>> Business Name:  [SOURCE_ORG_0001] Games Inc\n>>\n>> Unified Business Identifier (UBI):  605 624 997\n>>\n>>\n>>\n>>\n>>\n>> Dear Employer,\n>>\n>>\n>>\n>> I have been unable to reach you. I need more information about your\n>> company before I can set up your Washington State workers’ compensation\n>> account.\n>>\n>>\n>>\n>> *Please call or email me *with the following information:\n>>\n>>    - What is the nature of your business (including products/services\n>>    you provide and the duties of your workers)?\n>>    - Your Business License Application indicates you’re hiring\n>>       - Does this worker reside and work in Washington?\n>>       - Is this worker required to travel for their duties?\n>>       - What are the specific duties for this worker?\n>>    - Please correct or confirm the following:\n>>       - Mailing address:\n>>       - Physical address:\n>>       - Phone Number:\n>>       - First Date of Hire:\n>>    - Did you acquire this business?  No\n>>       - If so, who did you acquire it from?\n>>       - What date did the sale or change in ownership become final?\n>>\n>>\n>>\n>> *Please fax or mail me the following ownership information within ten\n>> days.  *Please complete and submit the *Change in Governing People*\n>> <https://dor.wa.gov/sites/default/files/2022-02/700306.pdf?uid=63ca6a01bb4c1>\n>> form, and return it to both Labor & Industries and Business Licensing\n>> Services.\n>>\n>>\n>>\n>> *Missing crucial information:*\n>>\n>>    - Full name of all owners\n>>    - Title of each owner (Ex: corporate Officer such as: President, VP,\n>>    LLC member or Manager)\n>>    - social Security number of each owner (do not email this\n>>    confidential information)\n>>    - Percentage of ownership for each owner (*must* add up to 100%)\n>>\n>>\n>>\n>> *What will happen if I don’t hear from you:*\n>>\n>> I will open your account with the owner information I have, as required,\n>> so your workers will be covered in the event of an on-the-job injury.\n>> Failure to provide this information may result in your account being set up\n>> incorrectly and *higher premiums* may incur.\n>>\n>>\n>>\n>> Thank you for your prompt response.\n>>\n>>\n>>\n>>\n>>\n>> Thank You,\n>>\n>>\n>>\n>> [PERSON_NAME_11622]\n>>\n>> Account Manager\n>>\n>> Employer Services\n>>\n>> *Department of Labor and Industries*\n>>\n>> *P.O. Box 44140 Olympia, WA 98504-4140*\n>>\n>> *Phone: [PHONE_4855] Fax: [PHONE_4854]*\n>>\n>>\n>>\n>> *File your Quarterly Report online:*\n>>\n>> *http://lni.wa.gov/quickfile <http://lni.wa.gov/quickfile> *\n>>\n>> *Make past due payments:*\n>>\n>> *http://www.lni.wa.gov/payabalancedue\n>> <http://www.lni.wa.gov/payabalancedue>*\n>>\n>>\n>>\n>>\n>>\n>' WHERE id = 'arthur.blake@harmonygames.co/<CAPBs_a6zM=or+nDw0YSrZ3Rmkvzr0fnVHNBaaRqx6vN6Uxrs_Q@mail.gmail.com>';
